def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The small color pattern acts as a 3-by-3 tile key. Locate its
    # nonzero cells and use the corresponding colors on the large 8-shape.
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] not in (0, 8)]
    if not points:
        return out

    r0 = min(r for r, c, v in points)
    c0 = min(c for r, c, v in points)
    key = {(r-r0, c-c0): v for r, c, v in points}

    # Large pattern is arranged in 4-by-4 tiles. Its tile positions align
    # with the key's colored cells.
    tiles = [
        (3, 2, 0, 0),
        (7, 6, 1, 1), (7, 10, 1, 2),
        (11, 2, 2, 0), (11, 6, 2, 1),
    ]
    for r, c, kr, kc in tiles:
        color = key.get((kr, kc))
        if color is None:
            continue
        for y in range(r, min(r + 4, h)):
            for x in range(c, min(c + 4, w)):
                if grid[y][x] == 8:
                    out[y][x] = color
    return out
